1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	
8	import org.springframework.samples.petclinic.model.Owner;
9	
10	/**
11	 * Derives an owner's deterministic {@code householdId}: the first 12 hex characters of SHA-256 over
12	 * (normalized last name + '|' + postcode). Two owners with the same last name and postcode share
13	 * the value automatically, so the household is keyed on (lastName, postcode) with no stored link.
14	 */
15	public final class HouseholdId {
16	
17	    private HouseholdId() {
18	    }
19	
20	    public static String of(Owner owner) {
21	        return of(owner.getLastName(), owner.getPostcode());
22	    }
23	
24	    public static String of(String lastName, String postcode) {
25	        String normalized = lastName == null ? "" : lastName.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
26	        return sha256hex(normalized + "|" + (postcode == null ? "" : postcode)).substring(0, 12);
27	    }
28	
29	    private static String sha256hex(String value) {
30	        try {
31	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
32	            StringBuilder hex = new StringBuilder(digest.length * 2);
33	            for (byte b : digest) {
34	                hex.append(String.format("%02x", b));
35	            }
36	            return hex.toString();
37	        }
38	        catch (NoSuchAlgorithmException e) {
39	            throw new IllegalStateException(e);
40	        }
41	    }
42	}
