8	
9	/**
10	 * Rejects a create request whose household (the {@code householdId} computed from last name and
11	 * postcode) matches an existing owner, so a second owner in the same household is a 409 via
12	 * {@link DuplicateHouseholdException}. A request that opts in with {@code sharesHousehold} true is
13	 * allowed through as a declared household member.
14	 */
15	public class EnsureUniqueHousehold {
16	
17	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
18	            throws DuplicateHouseholdException {
19	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
20	            return;
21	        }
22	        String householdId = HouseholdId.of(request.getLastName(), request.getPostcode());
23	        for (Owner owner : ownerRepository.findAll()) {
24	            if (!owner.isDeleted() && householdId.equals(owner.getHouseholdId())) {
25	                throw new DuplicateHouseholdException(request.getLastName(), request.getAddress());
26	            }
27	        }
28	    }
