2	
3	import java.util.List;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.MissingFieldsException;
8	
9	/**
10	 * Rewrites the telephone into E.164 form: keep a leading {@code '+'} and country code when
11	 * present, otherwise assume {@code '+61'} and drop a single leading {@code '0'} from the national
12	 * digits, stripping spaces, dashes and brackets. The result must carry 8 to 15 digits after the
13	 * {@code '+'} and the correct national-number length for its country code ({@code '+61'} needs 9
14	 * national digits, {@code '+1'} needs 10); the normalized value is stored back on the request so it is persisted and returned
15	 * as {@code telephone}. A non-conforming number is rejected with 400 via {@link MissingFieldsException}.
16	 */
17	public class NormalizeTelephone {
18	
19	    public void service(@Val OwnerFieldsDto request) throws MissingFieldsException {
20	        String raw = request.getTelephone().trim();
21	        String digits = raw.replaceAll("\\D", "");
22	        if (!raw.startsWith("+")) {
23	            digits = "61" + (digits.startsWith("0") ? digits.substring(1) : digits);
24	        }
25	        String country = digits.startsWith("61") ? "61" : digits.startsWith("1") ? "1" : "";
26	        int national = digits.length() - country.length();
27	        boolean wrongNationalLength = ("61".equals(country) && national != 9)
28	                || ("1".equals(country) && national != 10);
29	        if (wrongNationalLength || digits.length() < 8 || digits.length() > 15) {
30	            throw new MissingFieldsException(List.of("telephone"));
31	        }
32	        request.setTelephone("+" + digits);
33	    }
34	}
